CREATE PROCEDURE sp_process_pulled_labor AS /** ## Procedure Name       *[toast].[dbo].[sp_process_pulled_labor]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20250421      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Tab'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;                  DECLARE @SDate date         DECLARE @EDate date          SET @SDate = '2025-03-24' --convert(date,getdate()-14)          SET @EDate = convert(date,getdate()-1)  		declare @Params varchar(2000) = (select '9' as StoreGrouping, '243' as StoreGroup, @SDate as SDate, @EDate as EDate for json path) 		         select              hs.DateOfBusiness,             S.StoreID,              ajc.JobCodeId,             sum(hs.regularhours) RegularHours,             sum(hs.regularhours * hs.hourlywage) RegularDollars,             sum(hs.overtimehours) OTHours,             sum(hs.overtimehours * (hs.hourlywage*1.5)) OTDollars,             1 DayPartId         into #ShiftData 		from toast.dbo.hstShift hs         join toast.dbo.JobCodes jc         on hs.jobcode = jc.guid         join dev_aloha.dbo.jobcode ajc         on jc.code = ajc.toastjc         join toast.dbo.vw_live_toast_stores s         on hs.Store = s.guid         where ajc.owner = 1017         and DateOfBusiness between @SDate and @EDate         and ajc.jobcodeid not in (9503, 2222, 9500, 9505, 5555, 9502, 5018, 9504, 9506, 4444, 8888, 4275, 9501, 1111, 3333, 960, 6666, 9990, 1234, 7777, 20, 60, 99, 101, 105, 106, 900, 901, 902, 950, 977, 999)         and cast(datediff(second, hs.ClockIn, hs.ClockOut) as DECIMAL(12,2)) >= 60         group by s.storeid,ajc.jobcodeid, hs.DateOfBusiness         order by s.storeid, hs.DateOfBusiness, ajc.JobCodeId  		merge dev_aloha.dbo.tbl_LaborDataByDayPart lddp 		using #ShiftData sd 		on lddp.dateofbusiness = sd.dateofbusiness 		and lddp.RestaurantID = sd.storeid 		and lddp.jobcodeid = sd.jobcodeid 		and lddp.DayPartID = sd.DayPartID 		when matched then update set 			RegularHours = sd.RegularHours, 			RegularDollars = sd.RegularDollars, 			OTHours = sd.OTHours, 			OTDollars = sd.OTDollars 		when not matched by target then 			insert (DateOfBusiness, RestaurantID, JobCodeId, RegularHours, RegularDollars, OTHours, OTDollars, DayPartId) 			values (sd.DateOfBusiness, sd.StoreID, sd.JobCodeId, sd.RegularHours, sd.RegularDollars, sd.OTHours, sd.OTDollars, sd.DayPartId);          		drop table #ShiftData          -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END